import type {
  InfoBlockProps,
  InfoBlockVisualProps,
  InfoBlockContentProps,
  InfoBlockTitleProps,
  InfoBlockSubtitleProps,
  InfoBlockSublinkProps,
} from "./info-block.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { ArrowLineDownCurveRight } from "@exp-textura/icons";

import { InfoBlockClasses, StyledInfoBlock } from "./info-block.styles";
import { splitAnchorProps } from "./utils/splitAnchorProps";

const InfoBlockRoot = forwardRef<HTMLDivElement, InfoBlockProps>(
  (
    { className, variant = "default", children, ...props }: InfoBlockProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(InfoBlockClasses.root, className);

    return (
      <StyledInfoBlock
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledInfoBlock>
    );
  },
);
InfoBlockRoot.displayName = "InfoBlock";

const Visual: React.FC<InfoBlockVisualProps> = ({ children, className, ...props }) => (
  <div className={clsx(InfoBlockClasses.visual, className)} {...props}>
    {children}
  </div>
);
Visual.displayName = "InfoBlock.Visual";

const Content: React.FC<InfoBlockContentProps> = ({ children, className, ...props }) => (
  <div className={clsx(InfoBlockClasses.content, className)} {...props}>
    {children}
  </div>
);
Content.displayName = "InfoBlock.Content";

const Title: React.FC<InfoBlockTitleProps> = ({ children, className, ...props }) => (
  <div className={clsx(InfoBlockClasses.title, className)} {...props}>
    {children}
  </div>
);
Title.displayName = "InfoBlock.Title";

const Subtitle: React.FC<InfoBlockSubtitleProps> = ({ children, className, ...props }) => (
  <div className={clsx(InfoBlockClasses.subtitle, className)} {...props}>
    {children}
  </div>
);
Subtitle.displayName = "InfoBlock.Subtitle";

const Sublink: React.FC<InfoBlockSublinkProps> = ({
  children,
  className,
  icon = <ArrowLineDownCurveRight />,
  ...props
}) => {
  const [anchorProps, divProps] = splitAnchorProps(props);

  return (
    <div className={clsx(InfoBlockClasses.sublink, className)} {...divProps}>
      {icon}
      <a {...anchorProps}>{children}</a>
    </div>
  );
};
Sublink.displayName = "InfoBlock.Sublink";

type InfoBlockCompoundComponent = typeof InfoBlockRoot & {
  Visual: typeof Visual;
  Content: typeof Content;
  Title: typeof Title;
  Subtitle: typeof Subtitle;
  Sublink: typeof Sublink;
};

const InfoBlock = InfoBlockRoot as InfoBlockCompoundComponent;

InfoBlock.Visual = Visual;
InfoBlock.Content = Content;
InfoBlock.Title = Title;
InfoBlock.Subtitle = Subtitle;
InfoBlock.Sublink = Sublink;

export default InfoBlock;
